export class DynamicResourceAllocator {
  constructor() {
    this.resourceMap = new Map();
    this.eventSubscribers = new Map();
  }

  subscribe(eventType, callback) {
    if (!this.eventSubscribers.has(eventType)) {
      this.eventSubscribers.set(eventType, []);
    }
    this.eventSubscribers.get(eventType).push(callback);
  }

  publish(eventType, data) {
    if (this.eventSubscribers.has(eventType)) {
      this.eventSubscribers.get(eventType).forEach(callback => callback(data));
    }
  }

  allocateResources(agentId, priority) {
    this.resourceMap.set(agentId, priority);
    this.publish('resourceAllocated', { agentId, priority });
  }

  adjustAllocation(agentId, newPriority) {
    if (this.resourceMap.has(agentId)) {
      this.resourceMap.set(agentId, newPriority);
      this.publish('resourceAdjusted', { agentId, newPriority });
    }
  }
}